import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.Dd_iHz3e.js";const m=JSON.parse('{"title":"Step 0b: Project Pitch & Executive Summary","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),r={name:"00b-project-pitch.md"};function o(s,e,c,d,l,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="step-0b-project-pitch-executive-summary" tabindex="-1">Step 0b: Project Pitch &amp; Executive Summary <a class="header-anchor" href="#step-0b-project-pitch-executive-summary" aria-label="Permalink to &quot;Step 0b: Project Pitch &amp; Executive Summary&quot;">​</a></h1><p>This document provides rehearsable verbal pitches designed for technical interviews, hiring managers, and system architecture walkthroughs.</p><hr><h2 id="_30-second-elevator-pitch-spoken-first-person" tabindex="-1">30-Second Elevator Pitch (Spoken First-Person) <a class="header-anchor" href="#_30-second-elevator-pitch-spoken-first-person" aria-label="Permalink to &quot;30-Second Elevator Pitch (Spoken First-Person)&quot;">​</a></h2><p>&quot;Cooking Nexus is a full-stack smart kitchen operating system and culinary video platform that solves the chaotic friction of cooking with messy hands while keeping the kitchen safe. I built an Express and MongoDB backend that ingests real-time computer vision frames to log safety hazards like unattended smoke or stove fires, paired with a React 18 single-page application featuring vertical recipe reels and synchronized multi-timers. For intelligence, instead of training an expensive custom model from scratch, I integrated Google&#39;s Gemini 3 Flash through a streaming edge gateway that delivers real-time recipe generation, conversational substitution advice, and automated web recipe parsing directly into structured JSON. It bridges real-time IoT appliance awareness, creator video monetization, and generative culinary AI into a single seamless experience.&quot;</p><hr><h2 id="_2-minute-deep-technical-pitch-spoken-first-person" tabindex="-1">2-Minute Deep Technical Pitch (Spoken First-Person) <a class="header-anchor" href="#_2-minute-deep-technical-pitch-spoken-first-person" aria-label="Permalink to &quot;2-Minute Deep Technical Pitch (Spoken First-Person)&quot;">​</a></h2><p>&quot;Whenever someone cooks at home, they hit three major roadblocks: their hands are coated in flour or oil so they can&#39;t touch their phone screen; they risk burning their food or starting a grease fire if they get distracted; and traditional recipe websites are cluttered with ads and static text that don&#39;t scale ingredients or sync with your kitchen timers.</p><p>To solve this, I engineered Cooking Nexus as a dual-tier full-stack system.</p><p>On the backend, I built a high-throughput Node.js and Express 5 ingestion service backed by MongoDB and Mongoose. It exposes a specialized computer vision telemetry endpoint at <code>/api/vision</code> that receives frame classification data from kitchen cameras and logs hazard events like smoke or flare-ups with timestamps into a <code>SafetyLog</code> collection. For authentication, I engineered a passwordless Magic Link system using signed 15-minute JSON Web Tokens, eliminating traditional password credential risks.</p><p>On the frontend, I developed a modern React 18 and TypeScript application bundled with Vite. It includes over 30 interactive routes covering a TikTok-style vertical culinary reel player with swipe navigation, an interactive portion scaler that recalculates ingredient measurements dynamically, multi-stage parallel kitchen timers, and a weekly meal planning board that compiles a consolidated grocery shopping list organized by supermarket aisle.</p><p>For intelligence, I integrated Google&#39;s Gemini 3 Flash model via a Deno-based edge proxy using Server-Sent Events. The client in <code>ai-stream.ts</code> decodes incoming token chunks in real time, giving users zero perceived latency when chatting with the AI Chef. I also engineered specialized prompt guardrails: a &#39;ghost chef&#39; persona for side-by-side culinary technique comparisons, and an &#39;import&#39; mode that extracts raw, messy web recipe text into strict, validated JSON with cooking times and ingredient arrays.</p><p>What I&#39;m proudest of is the architectural separation: the backend handles fast, decoupled hazard ingestion and authentication, while the edge functions isolate the streaming AI inference, ensuring that heavy LLM traffic never blocks safety-critical kitchen telemetry.&quot;</p><hr><h2 id="_10-second-executive-hook" tabindex="-1">10-Second Executive Hook <a class="header-anchor" href="#_10-second-executive-hook" aria-label="Permalink to &quot;10-Second Executive Hook&quot;">​</a></h2><p>&quot;A smart kitchen platform combining real-time vision safety alerts, vertical recipe reels, and streaming Gemini-powered culinary intelligence for hands-free home cooking.&quot;</p>',16)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
